<?php
require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/layout.php';
require_user();$cart=cart_data();$_SESSION['checkout_id']??=uuid();page_header('Mi carrito','carrito');
?>
<main class="container page-section" id="contenido"><div class="page-heading"><div><h1>Mi carrito</h1></div><a class="text-link" href="<?=h(url('index.php#catalogo'))?>">Seguir comprando<?=icon('arrow')?></a></div>
<?php if(!$cart['items']):?><div class="empty-state empty-cart"><?=icon('cart')?><h2>Tu carrito está vacío</h2><a class="button" href="<?=h(url('index.php#catalogo'))?>">Ver productos<?=icon('arrow')?></a></div><?php else:?>
<div class="cart-layout"><section class="cart-items" aria-label="Productos en el carrito"><div class="cart-table-head"><span>Producto</span><span>Cantidad</span><span>Subtotal</span></div>
<?php foreach($cart['items'] as $line):$p=$line['product'];$invalid=!$p||$line['quantity']>(int)$p['stock'];?>
<article class="cart-item"><div class="cart-product"><a href="<?=h(url($p?'producto.php?id='.$p['id']:'index.php#catalogo'))?>"><img src="<?=h(image_url($p['imagen_url']??null))?>" alt="<?=h($p['nombre']??'Producto no disponible')?>" width="110" height="110"></a><div><span class="eyebrow"><?=h($p['marca']??'NO DISPONIBLE')?></span><h2><?php if($p):?><a href="<?=h(url('producto.php?id='.$p['id']))?>"><?=h($p['nombre'])?></a><?php else:?>Este producto fue retirado<?php endif;?></h2><span class="muted small"><?=$p?money($p['precio']).' por unidad':'Quitalo para continuar'?></span><?php if($invalid):?><p class="stock-warning"><?=$p?'Quedan '.(int)$p['stock'].' unidades. Ajustá la cantidad.':'El producto ya no está en el catálogo.'?></p><?php endif;?></div></div>
<div class="cart-quantity"><?php if($p):?><form data-api="cart_update" method="post" action="<?=h(url('api.php'))?>" class="quantity-form"><input type="hidden" name="id" value="<?=(int)$line['id']?>"><label class="sr-only" for="qty-<?=(int)$line['id']?>">Cantidad de <?=h($p['nombre'])?></label><div class="quantity-control"><button type="button" data-step="-1" aria-label="Quitar una unidad"><?=icon('minus')?></button><input type="number" name="cantidad" id="qty-<?=(int)$line['id']?>" value="<?=(int)$line['quantity']?>" min="1" max="<?=max(1,min(99,(int)$p['stock']))?>" required><button type="button" data-step="1" aria-label="Agregar una unidad"><?=icon('plus')?></button></div><button type="submit" class="quantity-save">Actualizar</button><p data-form-message class="form-message" role="alert" hidden></p></form><?php endif;?></div><div class="cart-line-total"><strong><?=money($line['subtotal'])?></strong><button class="remove-item" type="button" data-remove-cart="<?=(int)$line['id']?>"><?=icon('trash')?>Quitar</button></div></article>
<?php endforeach;?></section><aside class="order-summary"><h2>Resumen del pedido</h2><div class="summary-row"><span>Productos</span><span><?=$cart['units']?> unidades</span></div><div class="summary-row"><span>Subtotal</span><span><?=money($cart['total'])?></span></div><div class="summary-total"><span>Total</span><strong><?=money($cart['total'])?></strong></div><form data-api="checkout" method="post" action="<?=h(url('api.php'))?>"><input type="hidden" name="solicitud" value="<?=h($_SESSION['checkout_id'])?>"><p data-form-message class="form-message" role="alert" hidden></p><button class="button button-full" type="submit" <?=$cart['valid']?'':'disabled'?>>Confirmar compra<?=icon('arrow')?></button></form><?php if(!$cart['valid']):?><p class="stock-warning">Revisá los productos indicados antes de confirmar.</p><?php endif;?><p class="demo-note"><?=icon('lock')?>Compra de prueba, sin cobro.</p></aside></div>
<?php endif;?></main>
<dialog class="modal success-modal" id="purchase-dialog" data-success-dialog aria-labelledby="purchase-title"><span class="modal-symbol"><?=icon('check')?></span><h2 id="purchase-title">Compra exitosa</h2><div class="purchase-receipt"><span>Pedido <strong data-purchase-id></strong></span><span>Total <strong data-purchase-total></strong></span></div><p class="muted small">Compra de prueba, sin cobro.</p><a class="button button-full" href="<?=h(url('pedidos.php'))?>">Ver mis pedidos<?=icon('arrow')?></a><a class="text-link" href="<?=h(url('index.php#catalogo'))?>">Ver productos</a></dialog>
